// Reference solution
function truncateToMs(ts) {
  const m = /^(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d)(?:\.(\d+))?Z$/.exec(ts);
  if (!m) return null;
  return `${m[1]}.${((m[2] || '') + '000').slice(0, 3)}Z`;
}

